1	import type { LoadedAssets } from './assets.js';
2	import { sampleColormap } from './assets.js';
3	import { smoothstep } from './math.js';
4	import type { BlockRegistry } from './blocks.js';
5	
6	export const CHUNK_SIZE = 16;
7	export const WORLD_MIN_Y = -64;
8	export const WORLD_MAX_Y = 320;
9	export const WORLD_HEIGHT = WORLD_MAX_Y - WORLD_MIN_Y;
10	export const SEA_LEVEL = 63;
11	export const REGION_RADIUS = 6;
12	
13	const SKY_BITS = 9;
14	const Z_SHIFT = 9;
15	const Y_SHIFT = 18;
16	
17	export const BIOME = {
18	  ocean: 0, plains: 1, forest: 2, birch: 3, taiga: 4, desert: 5, savanna: 6,
19	  snowy: 7, beach: 8, mountains: 9, frozenOcean: 10, swamp: 11,
20	};
21	
22	const BIOME_DATA = [
23	  { name: 'ocean', temp: 0.5, humid: 0.5, water: '#3f76e4' },
24	  { name: 'plains', temp: 0.8, humid: 0.4, water: '#3f76e4' },
25	  { name: 'forest', temp: 0.7, humid: 0.8, water: '#3f76e4' },
26	  { name: 'birch_forest', temp: 0.6, humid: 0.6, water: '#3f76e4' },
27	  { name: 'taiga', temp: 0.25, humid: 0.8, water: '#287082' },
28	  { name: 'desert', temp: 2.0, humid: 0.0, water: '#32a598' },
29	  { name: 'savanna', temp: 1.2, humid: 0.0, water: '#2c8b9c' },
30	  { name: 'snowy_plains', temp: 0.0, humid: 0.5, water: '#3938c9' },
31	  { name: 'beach', temp: 0.8, humid: 0.4, water: '#3f76e4' },
32	  { name: 'mountains', temp: 0.2, humid: 0.3, water: '#3f76e4' },
33	  { name: 'frozen_ocean', temp: 0.0, humid: 0.5, water: '#3938c9' },
34	  { name: 'swamp', temp: 0.8, humid: 0.9, water: '#617b64' },
35	];
36	
37	function hash2i(x: number, z: number, seed: number): number {
38	  let h = seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(z | 0, 668265263);
39	  h = Math.imul(h ^ (h >>> 13), 1274126177);
40	  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
41	}
42	
43	function hash3i(x: number, y: number, z: number, seed: number): number {
44	  let h = seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 1103515245) ^ Math.imul(z | 0, 668265263);
45	  h = Math.imul(h ^ (h >>> 13), 1274126177);
46	  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
47	}
48	
49	function valueNoise2(x: number, z: number, seed: number): number {
50	  const xi = Math.floor(x), zi = Math.floor(z);
51	  const xf = x - xi, zf = z - zi;
52	  const u = xf * xf * (3 - 2 * xf);
53	  const v = zf * zf * (3 - 2 * zf);
54	  const a = hash2i(xi, zi, seed), b = hash2i(xi + 1, zi, seed);
55	  const c = hash2i(xi, zi + 1, seed), d = hash2i(xi + 1, zi + 1, seed);
56	  const ab = a + (b - a) * u, cd = c + (d - c) * u;
57	  return ab + (cd - ab) * v;
58	}
59	
60	function fbm2(x: number, z: number, octaves: number, seed: number): number {
61	  let sum = 0, amp = 0.5, norm = 0, fx = x, fz = z;
62	  for (let i = 0; i < octaves; i++) {
63	    sum += valueNoise2(fx, fz, seed + i * 1013) * amp;
