317	  /**
318	   * Height of the lake basin: a sandy shelf and deeper middle below sea level,
319	   * then a bench and rolling banks above it that dissolve into the base terrain.
320	   */
321	  private terrainHeight(x: number, z: number, lakeS: number): number {
322	    const base = this.baseHeight(x, z);
323	    if (lakeS < -64) return base;
324	    const bankNoise = (fbm2(x * 0.023, z * 0.023, 3, this.seed + 86) - 0.5) * 2;
325	    const fineNoise = (fbm2(x * 0.075, z * 0.075, 2, this.seed + 87) - 0.5) * 2;
326	    if (lakeS >= 0) {
327	      const shelf = smoothstep(0, 7, lakeS);
328	      const deep = smoothstep(8, 28, lakeS);
329	      let depth = 1 + 2.4 * shelf + 6.4 * deep;
330	      const rough = (fbm2(x * 0.055, z * 0.055, 2, this.seed + 91) - 0.5) * 4.6;
331	      depth += bankNoise * 2.6 * smoothstep(3, 12, lakeS);
332	      depth += rough * smoothstep(2, 9, lakeS);
333	      depth += fineNoise * 0.75 * smoothstep(4, 14, lakeS);
334	      return SEA_LEVEL - Math.max(0.6, depth);
335	    }
336	    const out = -lakeS;
337	    const slopeNoise = (fbm2(x * 0.009, z * 0.009, 2, this.seed + 90) - 0.5);
338	    const slope = 0.26 + 0.16 * smoothstep(0, 34, out) + slopeNoise * 0.16;
339	    const bench = Math.min(out, 5) * 0.2;
340	    let h = SEA_LEVEL + bench + Math.max(0, out - 5) * slope;
341	    h += bankNoise * 4.0 * smoothstep(0, 18, out);
342	    h += fineNoise * 0.9 * smoothstep(1, 8, out);
343	    const blend = smoothstep(24, 56, out + bankNoise * 10);
344	    return h * (1 - blend) + base * blend;
345	  }
346	
347	  private biomeAt(x: number, z: number, h: number): number {
348	    const t = fbm2(x * 0.0022, z * 0.0022, 3, this.seed + 11);
349	    const m = fbm2(x * 0.0022, z * 0.0022, 3, this.seed + 17);
350	    if (h < SEA_LEVEL - 2) return t < 0.24 ? BIOME.frozenOcean : BIOME.ocean;
351	    if (h <= SEA_LEVEL + 1) {
352	      if (h < SEA_LEVEL) return t < 0.24 ? BIOME.frozenOcean : BIOME.ocean;
353	      const shoreNoise = fbm2(x * 0.045, z * 0.045, 2, this.seed + 71);
354	      if (shoreNoise > 0.64) return t < 0.2 ? BIOME.snowy : BIOME.beach;
355	      if (t < 0.2) return BIOME.snowy;
356	      if (t > 0.74 && m < 0.42) return BIOME.desert;
357	      if (t < 0.32) return BIOME.taiga;
358	      if (m > 0.62) return BIOME.forest;
359	      return BIOME.plains;
360	    }
361	    if (h > 108) return BIOME.mountains;
362	    if (t < 0.2) return m > 0.5 ? BIOME.taiga : BIOME.snowy;
363	    if (t < 0.32) return BIOME.taiga;
364	    if (t > 0.74 && m < 0.42) return BIOME.desert;
365	    if (t > 0.66 && m < 0.55) return BIOME.savanna;
366	    if (m > 0.68 && h < SEA_LEVEL + 8 && t > 0.4) return BIOME.swamp;
367	    if (m > 0.62) return BIOME.forest;
368	    if (m > 0.5 && t < 0.62) return BIOME.birch;
369	    return BIOME.plains;
370	  }
371	
372	  private isTreeBiome(biome: number): boolean {
373	    return biome === BIOME.forest || biome === BIOME.birch || biome === BIOME.taiga ||
374	      biome === BIOME.plains || biome === BIOME.savanna || biome === BIOME.swamp;
375	  }
376	
377	  async generate(progress: (f: number, label: string) => void): Promise<void> {
378	    const total = this.gridSize * this.gridSize;
379	    let done = 0;
380	    for (let cx = this.originCX; cx < this.originCX + this.gridSize; cx++) {
381	      for (let cz = this.originCZ; cz < this.originCZ + this.gridSize; cz++) {
382	        this.generateChunk(cx, cz);
383	        done++;
384	        if (done % 8 === 0) {
385	          progress(0.72 + 0.14 * (done / total), `Generating terrain ${done}/${total}`);
386	          await new Promise(r => setTimeout(r, 0));
387	        }
388	      }
389	    }
390	    progress(0.87, 'Lighting the world');
391	    await new Promise(r => setTimeout(r, 0));
392	    this.computeLighting();
393	    progress(0.93, 'Placing features');
394	  }
395	
396	  private generateChunk(cx: number, cz: number): void {
397	    const c = this.createChunk(cx, cz);
398	    if (c.generated) return;
399	    c.generated = true;
400	    const baseX = cx * 16, baseZ = cz * 16;
401	    const { blocks, biomes, heights } = c;
402	    const ids = this.ids;
403	    const lake = new Float32Array(256);
404	
405	    // First pass: terrain shape and biome, so slopes can be read by the material pass.
406	    for (let lz = 0; lz < 16; lz++) {
407	      for (let lx = 0; lx < 16; lx++) {
408	        const x = baseX + lx, z = baseZ + lz;
409	        const ci = lz * 16 + lx;
410	        const ls = this.lakeSigned(x, z);
411	        const h = Math.floor(this.terrainHeight(x, z, ls));
412	        lake[ci] = ls;
413	        heights[ci] = h;
414	        biomes[ci] = this.biomeAt(x, z, h);
415	      }
416	    }
417	
418	    // Second pass: blocks and surface materials.
419	    for (let lz = 0; lz < 16; lz++) {
420	      for (let lx = 0; lx < 16; lx++) {
421	        const x = baseX + lx, z = baseZ + lz;
422	        const ci = lz * 16 + lx;
423	        const h = heights[ci];
424	        const biome = biomes[ci];
425	        const ls = lake[ci];
426	        const snowy = biome === BIOME.snowy || biome === BIOME.frozenOcean;
427	        const desert = biome === BIOME.desert;
428	        const beach = biome === BIOME.beach;
429	        const ocean = biome === BIOME.ocean || biome === BIOME.frozenOcean;
430	        const mountain = biome === BIOME.mountains;
431	        const nearLake = ls > -16;
432	
433	        let slope = 0;
434	        if (lx > 0) slope = Math.max(slope, Math.abs(h - heights[ci - 1]));
435	        if (lx < 15) slope = Math.max(slope, Math.abs(h - heights[ci + 1]));
436	        if (lz > 0) slope = Math.max(slope, Math.abs(h - heights[ci - 16]));
437	        if (lz < 15) slope = Math.max(slope, Math.abs(h - heights[ci + 16]));
438	
439	        let top = ids.grass_block;
440	        let filler = ids.dirt;
441	        if (desert) { top = ids.sand; filler = ids.sand; }
442	        else if (beach || ocean) {
443	          top = (h > 48 || h < 40) ? ids.sand : ids.gravel;
444	          filler = ids.sand;
445	          if (nearLake && h < SEA_LEVEL) {
446	            const sed = fbm2(x * 0.055, z * 0.055, 2, this.seed + 93);
447	            if (sed > 0.60) top = ids.gravel;
448	            else if (h < SEA_LEVEL - 4 && sed < 0.28) top = ids.clay;
449	          }
450	        }
451	        else if (snowy) { top = ids.snow_block; filler = ids.dirt; }
452	        else if (mountain) { top = h > 112 ? ids.snow_block : ids.stone; filler = ids.stone; }
453	        else if (biome === BIOME.swamp && h < SEA_LEVEL + 3) { top = ids.grass_block; filler = ids.dirt; }
454	
455	        // Patchy beach tongue above the waterline, with gravel bars.
456	        if (!desert && !snowy && !mountain && nearLake && h >= SEA_LEVEL && h <= SEA_LEVEL + 2) {
457	          const patch = fbm2(x * 0.075, z * 0.075, 2, this.seed + 94);
458	          if (h === SEA_LEVEL || (h === SEA_LEVEL + 1 && patch > 0.66) || (h === SEA_LEVEL + 2 && patch > 0.8)) {
459	            top = patch > 0.74 ? ids.gravel : ids.sand;
460	            filler = ids.sand;
461	          } else {
462	            top = ids.grass_block;
463	            filler = ids.dirt;
464	          }
465	        }
466	        // Occasional rocky outcrops on steeper grass banks.
467	        if (!desert && !snowy && !mountain && h > SEA_LEVEL + 2 && slope >= 1) {
468	          const outcrop = fbm2(x * 0.06, z * 0.06, 2, this.seed + 105);
469	          const roll = hash2i(x, z, this.seed + 106);
470	          if ((slope >= 2 && outcrop > 0.53 && roll < 0.5) || (outcrop > 0.72 && roll < 0.22)) {
471	            top = ids.stone;
472	            filler = ids.stone;
473	          }
474	        }
475	
476	        const maxY = Math.max(h, SEA_LEVEL);
477	        for (let y = WORLD_MIN_Y; y <= maxY; y++) {
478	          if (y < WORLD_MIN_Y + 2 + ((hash3i(x, y, z, this.seed + 5) * 2) | 0)) {
479	            blocks[this.idx(x, y, z)] = ids.bedrock;
480	            continue;
481	          }
482	          if (y <= h) {
483	            let id = ids.stone;
484	            if (y < -8) id = ids.deepslate;
485	            if (y > h - 4) {
486	              if (y === h) id = top;
487	              else id = filler;
488	            }
489	            if (y < h - 4 && y < 0 && y > h - 30) {
490	              const r = hash3i(x, y, z, this.seed + 23);
491	              if (r < 0.012) id = ids.coal_ore;
492	              else if (r < 0.019) id = ids.iron_ore;
493	              else if (r < 0.023) id = ids.copper_ore;
494	              else if (r < 0.0242) id = ids.diamond_ore;
495	            }
496	            if (desert && y > h - 5) id = y === h ? ids.sand : ids.sandstone;
497	            blocks[this.idx(x, y, z)] = id;
498	          } else {
499	            let fluid = ids.water;
500	            if (snowy && y === SEA_LEVEL) fluid = ids.ice;
501	            blocks[this.idx(x, y, z)] = fluid;
502	          }
503	        }
504	        if (snowy && h >= SEA_LEVEL && h < 100) {
505	          const sy = h + 1;
506	          if (sy < WORLD_MAX_Y) blocks[this.idx(x, sy, z)] = ids.snow;
507	        }
508	        if (mountain && h > 112) {
509	          const sy = h + 1;
510	          if (sy < WORLD_MAX_Y) blocks[this.idx(x, sy, z)] = ids.snow;
511	        }
512	      }
513	    }
514	
515	    // Boulders before trees so a rock spot is not also used for a trunk.
516	    for (let lz = 1; lz < 15; lz++) {
517	      for (let lx = 1; lx < 15; lx++) {
518	        const ci = lz * 16 + lx;
519	        this.placeBoulders(c, baseX + lx, baseZ + lz, heights[ci], lake[ci], biomes[ci]);
520	      }
521	    }
522	
523	    // Trees. Kept away from chunk borders so canopies stay inside; thinned near the shore.
524	    const treeSpots: [number, number][] = [];
525	    for (let lz = 3; lz < 13; lz++) {
526	      for (let lx = 3; lx < 13; lx++) {
527	        const x = baseX + lx, z = baseZ + lz;
528	        const ci = lz * 16 + lx;
529	        const h = heights[ci];
530	        if (h < SEA_LEVEL) continue;
531	        const biome = biomes[ci];
532	        const ground = this.getBlock(x, h, z);
533	        if (ground !== ids.grass_block) continue;
534	        if (this.getBlock(x, h + 1, z) !== 0) continue;
535	        const rnd = hash2i(x, z, this.seed + 41);
536	        if (!this.isTreeBiome(biome)) continue;
537	        let chance = this.treeChance(biome);
538	        if (lake[ci] > -12) chance *= 0.3;
539	        else if (lake[ci] > -24) chance *= 0.65;
540	        if (rnd >= chance) continue;
541	        if (treeSpots.some(([tx, tz]) => (tx - x) * (tx - x) + (tz - z) * (tz - z) < 12)) continue;
542	        treeSpots.push([x, z]);
543	        this.placeTree(c, x, h + 1, z, biome, hash2i(x, z, this.seed + 43));
544	      }
545	    }
546	
547	    // Cacti and ground cover, across the whole chunk (plants never cross borders).
548	    for (let lz = 0; lz < 16; lz++) {
549	      for (let lx = 0; lx < 16; lx++) {
550	        const x = baseX + lx, z = baseZ + lz;
551	        const ci = lz * 16 + lx;
552	        const h = heights[ci];
553	        const biome = biomes[ci];
554	        if (biome === BIOME.desert) {
555	          if (this.getBlock(x, h, z) === ids.sand && this.getBlock(x, h + 1, z) === 0 &&
556	            hash2i(x, z, this.seed + 47) < 0.018) {
557	            this.placeCactus(c, x, h + 1, z, hash2i(x, z, this.seed + 47));
558	          }
559	        }
560	        this.placeVegetation(c, x, z, h, biome, lake[ci]);
561	      }
562	    }
563	  }
564	
565	  private placeBoulders(c: Chunk, x: number, z: number, h: number, lakeS: number, biome: number): void {
566	    if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.desert ||
567	      biome === BIOME.beach || biome === BIOME.snowy) return;
568	    if (h < SEA_LEVEL + 1 || h > 105) return;
569	    const ids = this.ids;
570	    if (this.getBlock(x, h, z) !== ids.grass_block) return;
571	    if (this.getBlock(x, h + 1, z) !== 0) return;
572	    const chance = lakeS > -24 ? 0.004 : 0.002;
573	    if (hash2i(x, z, this.seed + 111) >= chance) return;
574	    const lx = x & 15, lz = z & 15;
575	    if (lx < 1 || lx > 14 || lz < 1 || lz > 14) return;
576	
577	    const size = 1 + ((hash2i(x, z, this.seed + 112) * 3) | 0); // 1-3 extra blocks
578	    const mossy = hash2i(x, z, this.seed + 113) < 0.4;
579	    const spots: [number, number][] = [[0, 0]];
580	    if (size >= 2) spots.push(hash2i(x, z, this.seed + 114) < 0.5 ? [1, 0] : [0, 1]);
581	    if (size >= 3) spots.push(hash2i(x, z, this.seed + 115) < 0.5 ? [-1, 0] : [0, -1]);
582	    for (let i = 0; i < spots.length; i++) {
583	      const nx = x + spots[i][0], nz = z + spots[i][1];
584	      if (nx < 0 || nz < 0) continue;
585	      const nlx = nx & 15, nlz = nz & 15;
586	      if (nlx < 0 || nlz < 0) continue;
587	      const nh = c.heights[nlz * 16 + nlx];
588	      if (Math.abs(nh - h) > 1) continue;
589	      if (c.blocks[this.idx(nx, nh, nz)] !== ids.grass_block) continue;
590	      if (c.blocks[this.idx(nx, nh + 1, nz)] !== 0) continue;
591	      const block = (i === 0 ? mossy : hash2i(nx, nz, this.seed + 116) < 0.35)
592	        ? ids.mossy_cobblestone : ids.stone;
593	      this.setLocal(c, nx, nh + 1, nz, block, true);
594	      if (i === 0 && size >= 3) this.setLocal(c, nx, nh + 2, nz, block, true);
595	    }
596	  }
597	
598	  private placeVegetation(c: Chunk, x: number, z: number, h: number, biome: number, lakeS: number): void {
599	    if (h < SEA_LEVEL || this.getBlock(x, h + 1, z) !== 0) return;
600	    const ids = this.ids;
601	    const ground = this.getBlock(x, h, z);
602	    if (ground === ids.sand || ground === ids.red_sand) {
603	      const deadChance = biome === BIOME.desert ? 0.006 : (lakeS > -18 ? 0.006 : 0);
604	      if (deadChance > 0 && hash2i(x, z, this.seed + 120) < deadChance) {
605	        this.setIfAir(c, x, h + 1, z, ids.dead_bush);
606	      }
607	      return;
608	    }
609	    if (ground !== ids.grass_block) return;
610	    if (biome === BIOME.snowy || biome === BIOME.frozenOcean || biome === BIOME.desert ||
611	      biome === BIOME.mountains) return;
612	
613	    const patch = fbm2(x * 0.047, z * 0.047, 2, this.seed + 93);
614	    const forest = biome === BIOME.forest || biome === BIOME.birch;
615	    const taiga = biome === BIOME.taiga;
616	    const swamp = biome === BIOME.swamp;
617	    const plains = biome === BIOME.plains || biome === BIOME.beach;
618	    const savanna = biome === BIOME.savanna;
619	
620	    // Compact flower clusters: a deterministic centre per 7x7 cell, one species per cluster.
621	    const cellX = Math.floor(x / 7), cellZ = Math.floor(z / 7);
622	    const clusterChance = forest ? 0.13 : plains ? 0.09 : savanna ? 0.035 : swamp ? 0.02 : taiga ? 0.012 : 0;
623	    if (clusterChance > 0 && hash2i(cellX, cellZ, this.seed + 96) < clusterChance) {
624	      const cx = cellX * 7 + 2 + ((hash2i(cellX, cellZ, this.seed + 97) * 3) | 0);
625	      const cz = cellZ * 7 + 2 + ((hash2i(cellX, cellZ, this.seed + 98) * 3) | 0);
626	      const dx = x - cx, dz = z - cz;
627	      if (dx * dx + dz * dz <= 4 && hash2i(x, z, this.seed + 99) < 0.55) {
628	        const flower = this.flowerIds[(hash2i(cellX, cellZ, this.seed + 100) * this.flowerIds.length) | 0];
629	        this.setIfAir(c, x, h + 1, z, flower);
630	        return;
631	      }
632	    }
633	
634	    let fernChance = 0;
635	    if (forest) fernChance = 0.012 + (patch > 0.5 ? 0.025 : 0);
636	    else if (taiga) fernChance = 0.045;
637	    else if (swamp) fernChance = 0.03;
638	    else if (plains) fernChance = 0.004;
639	    if (fernChance > 0 && hash2i(x, z, this.seed + 121) < fernChance) {
640	      this.setIfAir(c, x, h + 1, z, ids.fern);
641	      return;
642	    }
643	
644	    let grassChance = 0;
645	    if (forest) grassChance = patch > 0.42 ? 0.4 : 0.06;
646	    else if (plains) grassChance = patch > 0.46 ? 0.34 : 0.04;
647	    else if (taiga) grassChance = patch > 0.4 ? 0.26 : 0.05;
648	    else if (savanna) grassChance = patch > 0.5 ? 0.22 : 0.03;
649	    else if (swamp) grassChance = patch > 0.38 ? 0.36 : 0.1;
650	    if (hash2i(x, z, this.seed + 53) < grassChance) {
651	      this.setIfAir(c, x, h + 1, z, ids.short_grass);
652	    }
653	  }
654	
655	  private treeChance(biome: number): number {
656	    if (biome === BIOME.forest) return 0.035;
657	    if (biome === BIOME.birch) return 0.03;
658	    if (biome === BIOME.taiga) return 0.04;
659	    if (biome === BIOME.swamp) return 0.015;
660	    if (biome === BIOME.savanna) return 0.004;
661	    return 0.006;
662	  }
663	
664	  private setLocal(c: Chunk, x: number, y: number, z: number, id: number, overwrite = false): void {
665	    if (y < WORLD_MIN_Y || y >= WORLD_MAX_Y) return;
666	    const lx = x & 15, lz = z & 15;
667	    const i = this.idx(x, y, z);
668	    if (!overwrite && c.blocks[i] !== 0) return;
669	    c.blocks[i] = id;
670	  }
671	
672	  private setIfAir(c: Chunk, x: number, y: number, z: number, id: number): void {
673	    this.setLocal(c, x, y, z, id, false);
674	  }
675	
676	  private placeTree(c: Chunk, x: number, y: number, z: number, biome: number, rnd: number): void {
677	    const ids = this.ids;
678	    let log = ids.oak_log, leaves = ids.oak_leaves;
679	    let height = 4;
680	    const spruce = biome === BIOME.taiga;
681	    const birch = biome === BIOME.birch;
682	    if (birch) { log = ids.birch_log; leaves = ids.birch_leaves; height = 5 + ((rnd * 3) | 0); }
683	    else if (spruce) { log = ids.spruce_log; leaves = ids.spruce_leaves; height = 7 + ((rnd * 3) | 0); }
684	    else { height = 4 + ((rnd * 3) | 0); }
685	    if (this.getBlock(x, y + height, z) !== 0) return;
686	    for (let i = 0; i < height; i++) this.setLocal(c, x, y + i, z, log, true);
687	    const top = y + height - 1;
688	
689	    if (spruce) {
690	      // Conical, layered spruce with alternating branch tips and a spire.
691	      for (let ly = top; ly >= y + 2; ly--) {
692	        const d = top - ly;
693	        let r = d <= 1 ? 1 : d <= 4 ? 2 : 3;
694	        if (height < 9) r = Math.min(r, 2);
695	        for (let dx = -r; dx <= r; dx++) {
696	          for (let dz = -r; dz <= r; dz++) {
697	            if (Math.abs(dx) === r && Math.abs(dz) === r) continue;
698	            if (dx === 0 && dz === 0 && ly <= top) continue;
699	            this.setIfAir(c, x + dx, ly, z + dz, leaves);
700	          }
701	        }
702	        if (d >= 1 && d <= 4 && (d & 1) === 1) {
703	          const t = r + 1;
704	          this.setIfAir(c, x + t, ly, z, leaves);
705	          this.setIfAir(c, x - t, ly, z, leaves);
706	          this.setIfAir(c, x, ly, z + t, leaves);
707	          this.setIfAir(c, x, ly, z - t, leaves);
708	        }
709	      }
710	      this.setIfAir(c, x, top + 1, z, leaves);
711	      return;
712	    }
713	
714	    // Oak and birch: two broad 5x5 layers, then two 3x3 layers with a plus-shaped cap.
715	    for (let ly = top - 2; ly <= top + 1; ly++) {
716	      const layer = top + 1 - ly; // 0 = top cap, 3 = lowest 5x5 layer
717	      const r = layer <= 1 ? 1 : 2;
718	      for (let dx = -r; dx <= r; dx++) {
719	        for (let dz = -r; dz <= r; dz++) {
720	          if (dx === 0 && dz === 0 && ly <= top) continue;
721	          const corner = Math.abs(dx) === r && Math.abs(dz) === r;
722	          if (corner) {
723	            const roll = hash3i(x + dx, ly, z + dz, this.seed + 61);
724	            if (r === 2 && roll < (birch ? 0.55 : 0.3)) continue;
725	            if (r === 1 && roll < 0.5) continue;
726	          }
727	          this.setIfAir(c, x + dx, ly, z + dz, leaves);
728	        }
729	      }
730	    }
731	    // Small diagonal lobes on the upper layer widen the crown without making a flat disc.
732	    const lobeChance = birch ? 0.3 : 0.55;
733	    for (const [dx, dz] of [[2, 2], [-2, 2], [2, -2], [-2, -2]]) {
