    const cx = sx + fx * d, cz = sz + fz * d;
    for (let o = -2; o <= 2; o++) {
      const x = Math.round(cx - fz * o);
      const z = Math.round(cz + fx * o);
      for (let y = sy - 2; y <= sy + 10; y++) {

