    const n = names.get(id) ?? '';
    if (structural.has(n)) { count++; mat.set(n, (mat.get(n) ?? 0) + 1); }
  }
}
console.log('village structural blocks', count, [...mat.entries()].sort((x, y) => y[1] - x[1]).map(([n, c]) => `${n}:${c}`).join(' '));

t = performance.now();
generateStructures(b.w);
console.log('structures-only rerun ms', (performance.now() - t).toFixed(1));

// Light check: torches/lanterns exist and block light near them is > 0
let lit = 0, emitters = 0;
for (let z = v.z - 20; z <= v.z + 20; z++) for (let x = v.x - 20; x <= v.x + 20; x++) {
  for (let y = 70; y < 105; y++) {
    const id = a.w.getBlock(x, y, z);
    if (id === rocks.id('torch') || id === rocks.id('lantern')) {
      emitters++;
      if (a.w.getBlockLight(x, y, z) > 0) lit++;
    }
  }
}
