import { readFileSync } from 'node:fs';
import { World, SEA_LEVEL } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/world.ts';
import { BlockRegistry } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/blocks.ts';

const manifest = JSON.parse(readFileSync('C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/public/mc/manifest.json', 'utf8'));
const rocks = new BlockRegistry(manifest);
const data = new Uint8ClampedArray(256 * 256 * 4).fill(140);
const assets: any = { manifest, grassColormap: { width: 256, height: 256, data }, foliageColormap: { width: 256, height: 256, data } };
const w = new World(rocks, assets, 0x2602c0de);
await w.generate(() => {});
const water = rocks.id('water');
const leaves = new Set([rocks.id('oak_leaves'), rocks.id('birch_leaves'), rocks.id('spruce_leaves')]);
const logs = new Set([rocks.id('oak_log'), rocks.id('birch_log'), rocks.id('spruce_log')]);
const solid = rocks.solid;
const H = (x: number, z: number) => { const c = w.chunkAt(x >> 4, z >> 4); return c ? c.heights[((z & 15) << 4) | (x & 15)] : -999; };
const B = (x: number, y: number, z: number) => w.getBlock(x, y, z);

function estimate(mode: number): any {
  const waters: [number, number][] = [];
  for (const c of w.chunks.values()) for (let lz = 0; lz < 16; lz += 3) for (let lx = 0; lx < 16; lx += 3) {
    const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
    if (w.getBlock(x, SEA_LEVEL, z) === water && w.getBlock(x, SEA_LEVEL + 1, z) === 0) waters.push([x, z]);
  }
  let sx = 0, sz = 0; for (const [x, z] of waters) { sx += x; sz += z; }
  const cx = sx / waters.length, cz = sz / waters.length;
  let best: any = null;
  const rStep = mode === 2 ? 4 : 2;
  const aDiv = mode === 2 ? 0.5 : 1;
  for (let wi = 0; wi < waters.length; wi += 5) {
    const [wx, wz] = waters[wi];
    for (let r = 6; r <= 26; r += rStep) {
      const steps = Math.max(12, Math.round(r * 2 * aDiv));
      for (let a = 0; a < steps; a++) {
        const ang = (a / steps) * Math.PI * 2;
        const x = Math.round(wx + Math.cos(ang) * r), z = Math.round(wz + Math.sin(ang) * r);
        if (Math.abs(x) > 90 || Math.abs(z) > 90) continue;
        const h = H(x, z);
        if (h < SEA_LEVEL || h > SEA_LEVEL + 34) continue;
        const top = B(x, h, z);
        if (top !== rocks.id('grass_block') && top !== rocks.id('sand')) continue;
        const biome = w.biomeNameAt(x, z);
        if (biome === 'ocean' || biome === 'frozen_ocean' || biome === 'mountains') continue;
        let clear = true;
        for (let dy = 1; dy <= 5; dy++) { const above = B(x, h + dy, z); if (above !== 0 && solid[above]) { clear = false; break; } }
        if (!clear) continue;
        const twx = cx - x, twz = cz - z;
        const tl = Math.hypot(twx, twz) || 1;
        const fx = twx / tl, fz = twz / tl;
        let blocked = false;
        for (let t = 3; t <= 18; t += 3) if (H(Math.round(x + fx * t), Math.round(z + fz * t)) > h + 2) { blocked = true; break; }
        if (blocked) continue;
        let trees = 0;
        if (mode === 1) {
          for (let dz = -3; dz <= 3; dz += 2) for (let dx = -3; dx <= 3; dx += 2) for (let dy = 1; dy <= 10; dy += 2) if (leaves.has(B(x + dx, h + dy, z + dz))) trees += 4;
        } else if (mode === 2) {
          for (let dz = -3; dz <= 3; dz += 2) for (let dx = -3; dx <= 3; dx += 2) for (let dy = 1; dy <= 10; dy += 2) if (leaves.has(B(x + dx, h + dy, z + dz))) trees += 4;
        } else {
          for (let dz = -3; dz <= 3; dz++) for (let dx = -3; dx <= 3; dx++) for (let dy = 1; dy <= 10; dy++) if (leaves.has(B(x + dx, h + dy, z + dz))) trees++;
        }
        if (trees > 14) continue;
        let vista = 0;
        if (mode === 1) {
          for (let t = 4; t <= 12; t += 4) for (let o = -2; o <= 2; o += 2) for (let dy = 1; dy <= 9; dy += 3) {
            const px = Math.round(x + fx * t - fz * o), pz = Math.round(z + fz * t + fx * o);
            const id = B(px, h + dy, pz); if (leaves.has(id) || logs.has(id)) vista += 6;
          }
        } else if (mode === 2) {
          for (let t = 4; t <= 12; t += 4) for (let o = -2; o <= 2; o += 2) for (let dy = 1; dy <= 9; dy += 3) {
            const px = Math.round(x + fx * t - fz * o), pz = Math.round(z + fz * t + fx * o);
            const id = B(px, h + dy, pz); if (leaves.has(id) || logs.has(id)) vista += 6;
          }
        } else {
          for (let t = 4; t <= 12; t += 2) for (let o = -2; o <= 2; o += 2) for (let dy = 1; dy <= 9; dy++) {
            const px = Math.round(x + fx * t - fz * o), pz = Math.round(z + fz * t + fx * o);
            const id = B(px, h + dy, pz); if (leaves.has(id) || logs.has(id)) vista++;
          }
        }
        const yaw = Math.atan2(-twx, twz);
        const grassBonus = top === rocks.id('grass_block') ? 7 : 0;
        const heightBonus = h >= SEA_LEVEL + 3 && h <= SEA_LEVEL + 13 ? 8 : h > SEA_LEVEL + 13 ? 4 : 1;
        const distBonus = r >= 7 && r <= 18 ? 6 : 2;
        const score = grassBonus + heightBonus + distBonus + (top === rocks.id('sand') ? 2 : 0) - trees * 0.25 - vista * 0.4;
        if (!best || score > best.score) best = { x, z, y: h + 1, yaw, score };
      }
    }
  }
  return best;
}
for (const mode of [0, 1, 2]) {
  const t = performance.now();
  const s = estimate(mode);
  console.log('mode', mode, (performance.now() - t).toFixed(0) + 'ms', s);
}
console.log('actual', w.findSpawn());

