        let trees = 0;
        for (let dz = -3; dz <= 3; dz += 2) {
          for (let dx = -3; dx <= 3; dx += 2) {
            for (let dy = 1; dy <= 10; dy += 2) {
              if (leaves.has(this.get(x + dx, h + dy, z + dz))) trees += 4;
            }
          }
        }
