import { readFileSync } from 'node:fs';
import { World } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/world.ts';
import { BlockRegistry } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/blocks.ts';
const manifest = JSON.parse(readFileSync('C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/public/mc/manifest.json', 'utf8'));
const rocks = new BlockRegistry(manifest);
const data = new Uint8ClampedArray(256 * 256 * 4).fill(140);
const assets: any = { manifest, grassColormap: { width: 256, height: 256, data }, foliageColormap: { width: 256, height: 256, data } };
const w = new World(rocks, assets, 0x2602c0de);
await w.generate(() => {});
const names = new Map<number, string>();
for (const b of manifest.blocks) names.set(b.id, b.name);
const v = w.structureSites.find(s => s.type === 'village')!;
const ax = v.x, az = v.z;
const g = 84;
const leaves = new Set(['oak_leaves', 'birch_leaves', 'spruce_leaves']);
console.log('ground/path map (topmost block at h..h+1), village anchor', ax, az);
for (let z = az - 8; z <= az + 8; z++) {
  let row = '';
  for (let x = ax - 11; x <= ax + 10; x++) {
    const c = w.chunkAt(x >> 4, z >> 4);
    const h = c ? c.heights[((z & 15) << 4) | (x & 15)] : 0;
    let y = h;
    if (w.getBlock(x, h + 1, z) && !leaves.has(names.get(w.getBlock(x, h + 1, z)) ?? '')) y = h + 1;
    const id = w.getBlock(x, y, z);
    const n = names.get(id) ?? '';
    const abb: Record<string, string> = {
      'coarse_dirt': 'cD', 'gravel': 'gv', 'grass_block': 'gr', 'dirt': 'dr', 'oak_planks': 'PL',
      'cobblestone': 'cb', 'oak_log': 'lg', 'torch': 'tc', 'lantern': 'ln', 'water': '~~',
      'oak_stairs': 'st', 'oak_slab': 'sl', 'glass': 'gl', 'crafting_table': 'ct', 'bookshelf': 'bk',
      'moss_block': 'ms', 'sand': 'sd',
    };
    row += (abb[n] ?? (n ? n.slice(0, 2) : '..')).padEnd(3);
  }
  console.log(String(z).padStart(4), row);
}
// check each building footprint for stray leaf blocks
let strayLeaves = 0;
for (const s of w.structureSites) {
  const rad = s.type === 'watchtower' ? 2 : s.type === 'well' ? 1 : 3;
  for (let dz = -rad; dz <= rad; dz++) for (let dx = -rad; dx <= rad; dx++) {
    const x = s.x + dx, z = s.z + dz;
    for (let y = 80; y < 100; y++) {
      const n = names.get(w.getBlock(x, y, z)) ?? '';
      if (leaves.has(n)) { strayLeaves++; console.log('stray leaf', s.type, x, y, z); }
    }
  }
}
console.log('stray leaves in structure boxes', strayLeaves);
// well water and tower top
