1	import type { World } from './world.js';
2	
3	/**
4	 * Deterministic, vanilla-flavoured surface structures: a small oak village
5	 * near spawn (houses, workshop, well, watchtower) and a handful of scattered
6	 * ruins. Everything is built from blocks already present in the manifest.
7	 *
8	 * The generator runs after the terrain chunks exist but before computeLighting,
9	 * so torches and lanterns inside the structures light the world correctly.
10	 */
11	
12	export interface StructureSite {
13	  type: string;
14	  x: number;
15	  z: number;
16	}
17	
18	/** Kept in sync with world.ts. Importing them would create a runtime cycle. */
19	const SEA_LEVEL = 63;
20	const MIN_Y = -64;
21	const MAX_Y = 320;
22	
23	const BLOCK_NAMES = [
24	  'water', 'lava', 'ice', 'grass_block', 'dirt', 'coarse_dirt', 'gravel', 'sand',
25	  'stone', 'sandstone', 'cobblestone', 'mossy_cobblestone', 'stone_bricks',
26	  'mossy_stone_bricks', 'cracked_stone_bricks', 'moss_block', 'oak_log',
27	  'oak_planks', 'oak_stairs', 'oak_slab', 'glass', 'torch', 'lantern',
28	  'crafting_table', 'bookshelf', 'obsidian',
29	  'oak_leaves', 'birch_leaves', 'spruce_leaves', 'birch_log', 'spruce_log',
30	] as const;
31	
32	type BlockName = typeof BLOCK_NAMES[number];
33	type Ids = Record<BlockName, number>;
34	
35	function hash2(x: number, z: number, seed: number): number {
36	  let h = seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(z | 0, 668265263);
37	  h = Math.imul(h ^ (h >>> 13), 1274126177);
38	  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
39	}
40	
41	function hash3(x: number, y: number, z: number, seed: number): number {
42	  let h = seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 1103515245) ^ Math.imul(z | 0, 668265263);
43	  h = Math.imul(h ^ (h >>> 13), 1274126177);
44	  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
45	}
46	
47	interface RectInfo {
48	  g: number;
49	  lo: number;
50	  grass: number;
51	  cells: number;
52	}
53	
54	interface Spawn {
55	  x: number;
56	  y: number;
57	  z: number;
58	  yaw: number;
59	}
60	
61	const VILLAGE_BIOMES = new Set(['plains', 'birch_forest', 'forest', 'savanna', 'taiga']);
62	
63	class Builder {
64	  readonly sites: StructureSite[] = [];
65	  private readonly w: World;
66	  private readonly id: Ids;
67	  private readonly seed: number;
68	  private readonly occupied = new Set<string>();
69	  private spawn: Spawn = { x: 0, y: 0, z: 0, yaw: 0 };
70	  private viewX = 0;
71	  private viewZ = 1;
72	
73	  constructor(world: World) {
74	    this.w = world;
75	    this.seed = world.seed;
76	    const ids = {} as Ids;
77	    for (const name of BLOCK_NAMES) ids[name] = world.rocks.id(name);
78	    this.id = ids;
79	  }
80	
81	  run(): void {
82	    // A cheap coast-spawn estimate. The real findSpawn (called by main after
83	    // generate) does an expensive tree scan; this mirrors its topological
84	    // scoring only. Structures keep a wide margin, so a few blocks of
85	    // difference cannot put them inside the spawn bubble or the lake vista.
86	    this.spawn = this.estimateSpawn();
87	    this.viewX = -Math.sin(this.spawn.yaw);
88	    this.viewZ = Math.cos(this.spawn.yaw);
89	
90	    const village = this.findVillageSite();
91	    if (village) {
92	      this.buildVillage(village.x, village.z);
93	      this.sites.push({ type: 'village', x: village.x, z: village.z });
94	    }
95	    this.placeRuins(village);
96	    this.placeDesertRuin();
97	  }
98	
99	  /**
100	   * Fast approximation of World.findCoastSpawn: same scoring, but candidate
101	   * radii/angles and the tree/vista scans are subsampled. It lands within a
102	   * few blocks of the real spawn, and all structures keep >34 blocks of
103	   * clearance, so it cannot affect the player's spawn or first view.
104	   */
105	  private estimateSpawn(): Spawn {
106	    const water: [number, number][] = [];
107	    for (const c of this.w.chunks.values()) {
108	      for (let lz = 0; lz < 16; lz += 3) {
109	        for (let lx = 0; lx < 16; lx += 3) {
110	          const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
111	          if (this.get(x, SEA_LEVEL, z) === this.id.water && this.get(x, SEA_LEVEL + 1, z) === 0) {
112	            water.push([x, z]);
113	          }
114	        }
115	      }
116	    }
117	    if (!water.length) {
118	      return { x: 0, y: SEA_LEVEL + 4, z: 0, yaw: 0 };
119	    }
120	    let sumX = 0, sumZ = 0;
121	    for (const [x, z] of water) { sumX += x; sumZ += z; }
122	    const cx = sumX / water.length, cz = sumZ / water.length;
123	    const leaves = new Set([this.id.oak_leaves, this.id.birch_leaves, this.id.spruce_leaves]);
124	    const treeBlocks = new Set([this.id.oak_log, this.id.birch_log, this.id.spruce_log,
125	      this.id.oak_leaves, this.id.birch_leaves, this.id.spruce_leaves]);
126	
127	    let best: { x: number, y: number, z: number, score: number } | null = null;
128	    for (let wi = 0; wi < water.length; wi += 5) {
129	      const [wx, wz] = water[wi];
130	      for (let r = 6; r <= 26; r += 4) {
131	        const steps = Math.max(12, r);
132	        for (let a = 0; a < steps; a++) {
133	          const ang = (a / steps) * Math.PI * 2;
134	          const x = Math.round(wx + Math.cos(ang) * r);
135	          const z = Math.round(wz + Math.sin(ang) * r);
136	          if (Math.abs(x) > 90 || Math.abs(z) > 90) continue;
137	          const h = this.h(x, z);
138	          if (h < SEA_LEVEL || h > SEA_LEVEL + 34) continue;
139	          const top = this.get(x, h, z);
140	          const grass = top === this.id.grass_block;
141	          if (!grass && top !== this.id.sand) continue;
142	          const biome = this.w.biomeNameAt(x, z);
143	          if (biome === 'ocean' || biome === 'frozen_ocean' || biome === 'mountains') continue;
144	          let clear = true;
145	          for (let dy = 1; dy <= 5; dy++) {
146	            const above = this.get(x, h + dy, z);
147	            if (above !== 0 && this.w.rocks.solid[above]) { clear = false; break; }
148	          }
149	          if (!clear) continue;
150	
151	          const toWaterX = cx - x, toWaterZ = cz - z;
152	          const len = Math.hypot(toWaterX, toWaterZ) || 1;
153	          const fx = toWaterX / len, fz = toWaterZ / len;
154	          let blocked = false;
155	          for (let t = 3; t <= 18; t += 3) {
156	            if (this.h(Math.round(x + fx * t), Math.round(z + fz * t)) > h + 2) { blocked = true; break; }
157	          }
158	          if (blocked) continue;
159	
160	          // Subsample the canopy scan and scale the count (actual count is 4x).
161	          let trees = 0;
162	          for (let dz = -3; dz <= 3; dz += 2) {
163	            for (let dx = -3; dx <= 3; dx += 2) {
164	              for (let dy = 1; dy <= 10; dy += 2) {
165	                if (leaves.has(this.get(x + dx, h + dy, z + dz))) trees += 4;
166	              }
167	            }
168	          }
169	          if (trees > 14) continue;
170	          let vistaTrees = 0;
171	          for (let t = 4; t <= 12; t += 4) {
172	            for (let o = -2; o <= 2; o += 2) {
173	              const px = Math.round(x + fx * t - fz * o);
174	              const pz = Math.round(z + fz * t + fx * o);
175	              for (let dy = 1; dy <= 9; dy += 3) {
176	                if (treeBlocks.has(this.get(px, h + dy, pz))) vistaTrees += 6;
177	              }
178	            }
179	          }
180	          const heightBonus = h >= SEA_LEVEL + 3 && h <= SEA_LEVEL + 13 ? 8 : h > SEA_LEVEL + 13 ? 4 : 1;
181	          const distBonus = r >= 7 && r <= 18 ? 6 : 2;
182	          const score = (grass ? 7 : 0) + heightBonus + distBonus + (top === this.id.sand ? 2 : 0)
183	            - trees * 0.25 - vistaTrees * 0.4;
184	          if (!best || score > best.score) best = { x, y: h + 1, z, score };
185	        }
186	      }
187	    }
188	    if (!best) best = { x: 0, y: SEA_LEVEL + 4, z: 0, score: 0 };
189	    const yaw = Math.atan2(-(cx - best.x), cz - best.z);
190	    return { x: best.x, y: best.y, z: best.z, yaw };
191	  }
192	
193	  // ---------------- helpers ----------------
194	
195	  private inside(x: number, z: number): boolean {
196	    return x >= this.w.minWorldX && x <= this.w.maxWorldX && z >= this.w.minWorldZ && z <= this.w.maxWorldZ;
197	  }
198	
199	  private h(x: number, z: number): number {
200	    const c = this.w.chunkAt(x >> 4, z >> 4);
201	    if (!c) return -999;
202	    return c.heights[((z & 15) << 4) | (x & 15)];
203	  }
204	
205	  private put(x: number, y: number, z: number, block: number): void {
206	    if (y < MIN_Y || y >= MAX_Y || !this.inside(x, z)) return;
207	    this.w.setBlock(x, y, z, block);
208	  }
209	
210	  private get(x: number, y: number, z: number): number {
211	    if (y < MIN_Y || y >= MAX_Y || !this.inside(x, z)) return 0;
212	    return this.w.getBlock(x, y, z);
213	  }
214	
215	  private isLiquid(id: number): boolean {
216	    return id === this.id.water || id === this.id.lava || id === this.id.ice;
217	  }
218	
219	  private rectInfo(x0: number, z0: number, wid: number, dep: number): RectInfo | null {
220	    let g = -9999, lo = 9999, grass = 0, cells = 0;
221	    for (let z = z0; z < z0 + dep; z++) {
222	      for (let x = x0; x < x0 + wid; x++) {
223	        if (!this.inside(x, z)) return null;
224	        const h = this.h(x, z);
225	        if (h < SEA_LEVEL + 1 || h > 150) return null;
226	        const top = this.w.getBlock(x, h, z);
227	        if (top === 0 || this.isLiquid(top)) return null;
228	        const isGrass = top === this.id.grass_block || top === this.id.dirt || top === this.id.coarse_dirt;
229	        const isRuinGround = isGrass || top === this.id.sand || top === this.id.gravel ||
230	          top === this.id.stone || top === this.id.sandstone || top === this.id.moss_block;
231	        if (!isRuinGround) return null;
232	        if (isGrass) grass++;
233	        cells++;
234	        if (h > g) g = h;
235	        if (h < lo) lo = h;
236	      }
237	    }
238	    return { g, lo, grass, cells };
239	  }
240	
241	  /** Approximate distance to open water, sampled from the terrain height grid. */
242	  private waterDistance(x: number, z: number, maxR = 60): number {
243	    let best = maxR + 1;
244	    for (let r = 6; r <= maxR; r += 5) {
245	      for (let a = 0; a < 24; a++) {
246	        const ang = (a / 24) * Math.PI * 2;
247	        const px = Math.round(x + Math.cos(ang) * r);
248	        const pz = Math.round(z + Math.sin(ang) * r);
249	        const h = this.h(px, pz);
250	        if (h !== -999 && h < SEA_LEVEL) {
251	          if (r < best) best = r;
252	          break;
253	        }
254	      }
255	    }
256	    return best;
257	  }
258	
259	  private maxGround(x0: number, z0: number, wid: number, dep: number): number {
260	    let g = -9999;
261	    for (let z = z0; z < z0 + dep; z++) {
262	      for (let x = x0; x < x0 + wid; x++) {
263	        const h = this.h(x, z);
264	        if (h > g) g = h;
265	      }
266	    }
267	    return g;
268	  }
269	
270	  /** Cheap 3x3 height probe used to skip obviously sloped site candidates. */
271	  private roughFlat(x0: number, z0: number, wid: number, dep: number): boolean {
272	    let lo = 9999, hi = -9999;
273	    for (const fz of [0, 0.5, 1]) {
274	      for (const fx of [0, 0.5, 1]) {
275	        const h = this.h(x0 + Math.round((wid - 1) * fx), z0 + Math.round((dep - 1) * fz));
276	        if (h < SEA_LEVEL + 1) return false;
277	        if (h < lo) lo = h;
278	        if (h > hi) hi = h;
279	      }
280	    }
281	    return hi - lo <= 3;
282	  }
283	
284	  private clearColumn(x: number, z: number, from: number, to: number): void {
285	    for (let y = from; y <= to && y < MAX_Y; y++) this.put(x, y, z, 0);
286	  }
287	
288	  /**
289	   * Clear trees/plants over a rectangle and fill a level foundation up to g.
290	   * Heights are read before any writes, so this is deterministic.
291	   */
292	  private prepare(x0: number, z0: number, wid: number, dep: number, g: number, clearHeight: number): void {
293	    for (let z = z0; z < z0 + dep; z++) {
294	      for (let x = x0; x < x0 + wid; x++) {
295	        const h = this.h(x, z);
296	        this.occupied.add(`${x},${z}`);
297	        this.clearColumn(x, z, h + 1, h + clearHeight);
298	        for (let y = h + 1; y < g; y++) this.put(x, y, z, this.id.cobblestone);
299	        this.put(x, g, z, this.id.dirt);
300	      }
301	    }
302	  }
303	
304	  private ruinBlock(x: number, y: number, z: number): number {
305	    const r = hash3(x, y, z, this.seed + 1207);
306	    if (r < 0.3) return this.id.cobblestone;
307	    if (r < 0.48) return this.id.mossy_cobblestone;
308	    if (r < 0.72) return this.id.stone_bricks;
309	    if (r < 0.88) return this.id.mossy_stone_bricks;
310	    return this.id.cracked_stone_bricks;
311	  }
312	
313	  // ---------------- village ----------------
314	
315	  private findVillageSite(): { x: number; z: number } | null {
316	    const pass = (relaxed: boolean): { x: number; z: number; score: number } | null => {
317	      let best: { x: number; z: number; score: number } | null = null;
318	      for (let z = this.w.minWorldZ + 10; z <= this.w.maxWorldZ - 10; z += 2) {
319	        for (let x = this.w.minWorldX + 12; x <= this.w.maxWorldX - 12; x += 2) {
320	          const dx = x - this.spawn.x, dz = z - this.spawn.z;
321	          const d = Math.hypot(dx, dz);
322	          const minD = relaxed ? 45 : 50;
323	          const maxD = relaxed ? 88 : 82;
324	          if (d < minD || d > maxD) continue;
325	          const frontal = (dx * this.viewX + dz * this.viewZ) / Math.max(1, d);
326	          if (frontal > (relaxed ? 0.4 : 0.2)) continue;
327	          if (!this.roughFlat(x - 10, z - 8, 21, 18)) continue;
328	          const info = this.rectInfo(x - 10, z - 8, 21, 18);
329	          if (!info) continue;
330	          const spread = info.g - info.lo;
331	          if (spread > (relaxed ? 3 : 2)) continue;
332	          if (!relaxed && info.grass < info.cells * 0.85) continue;
333	          const biome = this.w.biomeNameAt(x, z);
334	          if (relaxed ? (biome === 'ocean' || biome === 'frozen_ocean' || biome === 'snowy_plains') : !VILLAGE_BIOMES.has(biome)) continue;
335	          if (this.waterDistance(x, z, 58) < (relaxed ? 36 : 46)) continue;
336	          const mid = (info.g + info.lo) / 2;
337	          let score = spread * 10;
338	          score += Math.abs(d - 66) * 0.22;
339	          score += Math.abs(mid - 78) * 0.05;
340	          score += Math.max(0, frontal) * 5;
341	          if (biome === 'plains') score -= 2;
342	          else if (biome === 'birch_forest') score -= 0.8;
343	          else if (biome === 'forest') score += 0.8;
344	          else if (biome === 'taiga') score += 1.8;
345	          score += hash2(x, z, this.seed + 501) * 1.1;
346	          if (!best || score < best.score) best = { x, z, score };
347	        }
348	      }
349	      return best;
350	    };
351	    let best = pass(false);
352	    if (!best) best = pass(true);
353	    return best ? { x: best.x, z: best.z } : null;
354	  }
355	
356	  private buildVillage(ax: number, az: number): void {
357	    // The four buildings face the central street; all offsets stay within the
358	    // flat 21x18 plot checked by findVillageSite.
359	    if (this.buildHouse(ax - 9, az - 7, 7, 5, 3, 1, 1)) {
360	      this.sites.push({ type: 'house', x: ax - 6, z: az - 5 });
361	    }
362	    if (this.buildHouse(ax + 3, az - 7, 7, 5, 3, 2, 2)) {
363	      this.sites.push({ type: 'workshop', x: ax + 6, z: az - 5 });
364	    }
365	    if (this.buildWell(ax - 3, az + 2)) this.sites.push({ type: 'well', x: ax - 2, z: az + 3 });
366	    if (this.buildTower(ax + 4, az + 3)) this.sites.push({ type: 'watchtower', x: ax + 6, z: az + 5 });
367	
368	    const street: [number, number][] = [];
369	    for (let z = az - 2; z <= az + 6; z++) { street.push([ax, z]); street.push([ax + 1, z]); }
370	    for (let x = ax - 6; x <= ax - 1; x++) street.push([x, az - 2]);
371	    for (let x = ax + 2; x <= ax + 6; x++) street.push([x, az - 2]);
372	    for (let x = ax + 2; x <= ax + 3; x++) street.push([x, az + 5]);
373	    for (const [x, z] of street) this.pathCell(x, z);
374	
375	    this.lanternPost(ax - 2, az - 1);
376	    this.lanternPost(ax + 2, az + 7);
377	  }
378	
379	  private buildHouse(
380	    x0: number, z0: number, wid: number, dep: number, wallH: number,
381	    tables: number, shelves: number,
382	  ): boolean {
383	    const info = this.rectInfo(x0, z0, wid, dep);
384	    if (!info || info.g - info.lo > 2) return false;
385	    const g = info.g;
386	    this.prepare(x0, z0, wid, dep, g, wallH + 16);
387	
388	    const frontZ = z0 + dep - 1;
389	    const doorX = x0 + (wid >> 1);
390	
391	    // Foundation/floor: cobble edge, plank interior.
392	    for (let z = z0; z < z0 + dep; z++) {
393	      for (let x = x0; x < x0 + wid; x++) {
394	        const edge = x === x0 || x === x0 + wid - 1 || z === z0 || z === z0 + dep - 1;
395	        this.put(x, g, z, edge ? this.id.cobblestone : this.id.oak_planks);
396	      }
397	    }
398	
399	    // Corner logs and plank walls.
400	    for (let y = g + 1; y <= g + wallH; y++) {
401	      for (let x = x0; x < x0 + wid; x++) {
402	        const corner = x === x0 || x === x0 + wid - 1;
403	        this.put(x, y, z0, corner ? this.id.oak_log : this.id.oak_planks);
404	        this.put(x, y, frontZ, corner ? this.id.oak_log : this.id.oak_planks);
405	      }
406	      for (let z = z0 + 1; z < frontZ; z++) {
407	        this.put(x0, y, z, y === g + 1 ? this.id.oak_log : this.id.oak_planks);
408	        this.put(x0 + wid - 1, y, z, y === g + 1 ? this.id.oak_log : this.id.oak_planks);
409	      }
410	    }
411	
412	    // Door opening (two blocks high) and glass windows.
413	    this.put(doorX, g + 1, frontZ, 0);
414	    this.put(doorX, g + 2, frontZ, 0);
415	    this.put(x0 + 1, g + 2, frontZ, this.id.glass);
416	    this.put(x0 + wid - 2, g + 2, frontZ, this.id.glass);
417	    this.put(x0 + 1, g + 2, z0, this.id.glass);
418	    this.put(x0 + wid - 2, g + 2, z0, this.id.glass);
419	    this.put(x0, g + 2, z0 + 2, this.id.glass);
420	    this.put(x0 + wid - 1, g + 2, z0 + 2, this.id.glass);
421	
422	    // Interior furniture along the back wall.
423	    this.put(x0 + 1, g + 1, z0 + 1, this.id.crafting_table);
424	    this.put(x0 + 2, g + 1, z0 + 1, this.id.bookshelf);
425	    for (let i = 0; i < tables; i++) this.put(x0 + 3 + i, g + 1, z0 + 1, this.id.crafting_table);
426	    for (let i = 0; i < shelves; i++) this.put(x0 + 1 + i, g + 1, z0 + 2, this.id.bookshelf);
427	    const torchX = x0 + wid - 2, torchZ = z0 + 2;
428	    if (this.get(torchX, g + 1, torchZ) === 0) this.put(torchX, g + 1, torchZ, this.id.torch);
429	
430	    // Stepped hip roof: stair eaves, slab courses, one overhang.
431	    // Clear the overhang ring too, otherwise a tree can poke through the eaves.
432	    for (let z = z0 - 1; z <= z0 + dep; z++) {
433	      for (let x = x0 - 1; x <= x0 + wid; x++) {
434	        const outside = x < x0 || x > x0 + wid - 1 || z < z0 || z > z0 + dep - 1;
435	        if (outside) this.clearColumn(x, z, this.h(x, z) + 1, this.h(x, z) + wallH + 16);
436	        const dx = x < x0 || x > x0 + wid - 1 ? -1 : Math.min(x - x0, x0 + wid - 1 - x);
437	        const dz = z < z0 || z > z0 + dep - 1 ? -1 : Math.min(z - z0, z0 + dep - 1 - z);
438	        const dmin = Math.max(0, Math.min(dx, dz));
439	        const y = g + wallH + 1 + dmin;
440	        const eave = dx <= 0 || dz <= 0;
441	        this.put(x, y, z, eave ? this.id.oak_stairs : this.id.oak_slab);
442	      }
443	    }
444	
445	    // Torch on a cobble sconce beside the door.
446	    this.put(doorX - 2, g + 2, frontZ + 1, this.id.cobblestone);
447	    this.put(doorX - 2, g + 3, frontZ + 1, this.id.torch);
448	    return true;
449	  }
450	
451	  private buildWell(x0: number, z0: number): boolean {
452	    const info = this.rectInfo(x0, z0, 3, 3);
453	    if (!info || info.g - info.lo > 2) return false;
454	    const g = info.g;
455	    this.prepare(x0, z0, 3, 3, g, 10);
456	
457	    for (let z = z0; z < z0 + 3; z++) {
458	      for (let x = x0; x < x0 + 3; x++) {
459	        const rim = x === x0 || x === x0 + 2 || z === z0 || z === z0 + 2;
460	        this.put(x, g, z, this.id.cobblestone);
461	        if (rim) this.put(x, g + 1, z, this.id.cobblestone);
462	      }
463	    }
464	    this.put(x0 + 1, g, z0 + 1, this.id.water);
465	    for (const [dx, dz] of [[0, 0], [2, 0], [0, 2], [2, 2]]) {
466	      this.put(x0 + dx, g + 2, z0 + dz, this.id.oak_log);
467	    }
468	    for (let z = z0; z < z0 + 3; z++) {
469	      for (let x = x0; x < x0 + 3; x++) this.put(x, g + 3, z, this.id.oak_slab);
470	    }
471	    this.put(x0 + 1, g + 2, z0, this.id.torch);
472	    return true;
473	  }
474	
475	  private buildTower(x0: number, z0: number): boolean {
476	    const info = this.rectInfo(x0, z0, 5, 5);
477	    if (!info || info.g - info.lo > 2) return false;
478	    const g = info.g;
479	    this.prepare(x0, z0, 5, 5, g, 22);
480	    const frontZ = z0 + 4;
481	
482	    for (let z = z0; z < z0 + 5; z++) {
483	      for (let x = x0; x < x0 + 5; x++) this.put(x, g, z, this.id.cobblestone);
484	    }
485	    for (let y = g + 1; y <= g + 8; y++) {
486	      for (let x = x0; x < x0 + 5; x++) {
487	        const corner = x === x0 || x === x0 + 4;
488	        const block = y <= g + 2 ? this.id.cobblestone : this.id.oak_planks;
489	        this.put(x, y, z0, corner ? this.id.oak_log : block);
490	        this.put(x, y, frontZ, corner ? this.id.oak_log : block);
491	      }
492	      for (let z = z0 + 1; z < frontZ; z++) {
493	        const block = y <= g + 2 ? this.id.cobblestone : this.id.oak_planks;
494	        this.put(x0, y, z, y === g + 1 || y === g + 2 ? this.id.oak_log : block);
495	        this.put(x0 + 4, y, z, y === g + 1 || y === g + 2 ? this.id.oak_log : block);
496	      }
497	    }
498	    // Door on the west face, facing the village street.
499	    this.put(x0, g + 1, z0 + 2, 0);
500	    this.put(x0, g + 2, z0 + 2, 0);
501	    this.put(x0 + 2, g + 5, z0, this.id.glass);
502	    this.put(x0 + 2, g + 5, frontZ, this.id.glass);
503	    this.put(x0, g + 5, z0 + 2, this.id.glass);
504	    this.put(x0 + 4, g + 5, z0 + 2, this.id.glass);
505	    this.put(x0 + 2, g + 1, z0 + 2, this.id.torch);
506	
507	    // Open watch platform with a crenellated parapet and a lantern.
508	    for (let z = z0; z < z0 + 5; z++) {
509	      for (let x = x0; x < x0 + 5; x++) this.put(x, g + 9, z, this.id.oak_planks);
510	    }
511	    for (let z = z0; z < z0 + 5; z++) {
512	      for (let x = x0; x < x0 + 5; x++) {
513	        const rim = x === x0 || x === x0 + 4 || z === z0 || z === z0 + 4;
514	        if (!rim) continue;
515	        if (hash2(x, z, this.seed + 822) < 0.28) continue;
516	        this.put(x, g + 10, z, this.id.cobblestone);
517	        if ((x + z) % 3 === 0) this.put(x, g + 11, z, this.id.cobblestone);
518	      }
519	    }
520	    this.put(x0 + 2, g + 10, z0 + 2, this.id.lantern);
521	    return true;
522	  }
523	
524	  private pathCell(x: number, z: number): void {
525	    if (!this.inside(x, z) || this.occupied.has(`${x},${z}`)) return;
526	    const h = this.h(x, z);
527	    if (h < SEA_LEVEL + 1) return;
528	    const top = this.get(x, h, z);
529	    if (top !== this.id.grass_block && top !== this.id.dirt && top !== this.id.coarse_dirt &&
530	      top !== this.id.gravel && top !== this.id.sand) return;
531	    // Only dig out a full tree when the path actually hits a trunk. Deep
532	    // clearing everywhere would erase roof eaves that overhang the street.
533	    const obstructed = this.get(x, h + 1, z) !== 0;
534	    this.clearColumn(x, z, h + 1, obstructed ? h + 15 : h + 3);
535	    const r = hash2(x, z, this.seed + 733);
536	    const block = r < 0.7 ? this.id.coarse_dirt : r < 0.9 ? this.id.gravel : this.id.dirt;
537	    this.put(x, h, z, block);
538	  }
539	
540	  private lanternPost(x: number, z: number): void {
541	    if (!this.inside(x, z) || this.occupied.has(`${x},${z}`)) return;
542	    const h = this.h(x, z);
543	    if (h < SEA_LEVEL + 1) return;
544	    const top = this.get(x, h, z);
545	    if (top !== this.id.grass_block && top !== this.id.dirt && top !== this.id.coarse_dirt && top !== this.id.gravel) return;
546	    const obstructed = this.get(x, h + 1, z) !== 0;
547	    this.clearColumn(x, z, h + 1, obstructed ? h + 15 : h + 4);
548	    this.put(x, h + 1, z, this.id.oak_log);
549	    this.put(x, h + 2, z, this.id.oak_log);
550	    this.put(x, h + 3, z, this.id.lantern);
551	  }
552	
553	  // ---------------- ruins ----------------
554	
555	  private placeRuins(village: { x: number; z: number } | null): void {
556	    const candidates: { x: number; z: number; score: number }[] = [];
557	    for (let z = this.w.minWorldZ + 5; z <= this.w.maxWorldZ - 5; z += 3) {
558	      for (let x = this.w.minWorldX + 5; x <= this.w.maxWorldX - 5; x += 3) {
559	        const dx = x - this.spawn.x, dz = z - this.spawn.z;
560	        const d = Math.hypot(dx, dz);
561	        if (d < 34 || d > 92) continue;
562	        const frontal = (dx * this.viewX + dz * this.viewZ) / Math.max(1, d);
563	        if (d < 54 && frontal > 0.45) continue;
564	        if (village && Math.hypot(x - village.x, z - village.z) < 24) continue;
565	        if (!this.roughFlat(x - 4, z - 3, 9, 7)) continue;
566	        const info = this.rectInfo(x - 4, z - 3, 9, 7);
567	        if (!info || info.g - info.lo > 2) continue;
568	        if (this.waterDistance(x, z, 54) < 44) continue;
569	        const score = hash2(x, z, this.seed + 901) + (info.g - info.lo) * 0.4 + (info.cells - info.grass) * 0.02;
570	        candidates.push({ x, z, score });
571	      }
572	    }
573	    candidates.sort((a, b) => a.score - b.score);
574	
575	    const chosen: { x: number; z: number }[] = [];
576	    for (const c of candidates) {
577	      if (chosen.length >= 4) break;
578	      if (village && Math.hypot(c.x - village.x, c.z - village.z) < 20) continue;
579	      if (chosen.some(s => Math.hypot(s.x - c.x, s.z - c.z) < 18)) continue;
580	      chosen.push({ x: c.x, z: c.z });
581	    }
582	
583	    const types = ['ruined_portal', 'campsite', 'ruined_wall', 'ruined_hut'];
584	    for (let i = 0; i < chosen.length; i++) {
585	      const { x, z } = chosen[i];
586	      const type = types[i % types.length];
587	      let ok = false;
588	      if (type === 'ruined_portal') ok = this.buildPortal(x - 3, z - 3);
589	      else if (type === 'campsite') ok = this.buildCampsite(x - 3, z - 3);
590	      else if (type === 'ruined_wall') ok = this.buildRuinWalls(x - 3, z - 2, 7, 5, 0);
591	      else ok = this.buildRuinWalls(x - 3, z - 2, 7, 5, 1);
592	      if (ok) this.sites.push({ type, x, z });
593	    }
594	  }
595	
596	  /** Flatten and clear a roughly square ruin pad, returning its floor height. */
597	  private ruinPad(x0: number, z0: number, wid: number, dep: number, desert = false): number | null {
598	    const info = this.rectInfo(x0, z0, wid, dep);
599	    if (!info || info.g - info.lo > 2) return null;
600	    const g = info.g;
601	    for (let z = z0; z < z0 + dep; z++) {
602	      for (let x = x0; x < x0 + wid; x++) {
603	        const h = this.h(x, z);
604	        this.clearColumn(x, z, h + 1, h + 16);
605	        for (let y = h + 1; y < g; y++) this.put(x, y, z, desert ? this.id.sand : this.id.dirt);
606	        const r = hash2(x, z, this.seed + 955);
607	        if (h === g) {
608	          if (desert) {
609	            if (r < 0.2) this.put(x, g, z, this.id.sandstone);
610	          } else if (r < 0.16) {
611	            this.put(x, g, z, this.id.moss_block);
612	          } else if (r < 0.28) {
613	            this.put(x, g, z, r < 0.22 ? this.id.gravel : this.id.coarse_dirt);
614	          }
615	        } else {
616	          this.put(x, g, z, desert ? this.id.sand : (r < 0.3 ? this.id.moss_block : this.id.coarse_dirt));
617	        }
618	      }
619	    }
620	    return g;
621	  }
622	
623	  private buildPortal(x0: number, z0: number): boolean {
624	    const g = this.ruinPad(x0, z0, 7, 6);
625	    if (g === null) return false;
626	    const zf = z0 + 3;
627	    for (let x = x0; x < x0 + 7; x++) {
628	      for (let z = z0 + 2; z <= z0 + 4; z++) this.put(x, g, z, this.id.stone_bricks);
629	    }
630	    // 4x5 obsidian frame with a missing top corner and one shattered side.
631	    for (let y = g + 1; y <= g + 5; y++) {
632	      for (let x = x0 + 1; x <= x0 + 4; x++) {
633	        const frame = y === g + 1 || y === g + 5 || x === x0 + 1 || x === x0 + 4;
634	        if (!frame) continue;
635	        if (y === g + 5 && (x === x0 + 1 || x === x0 + 4)) continue;
636	        if (x === x0 + 1 && y === g + 3) continue;
637	        this.put(x, y, zf, this.id.obsidian);
638	      }
639	    }
640	    // Broken obsidian debris and rubble on the pad.
641	    for (let i = 0; i < 9; i++) {
642	      const dx = x0 + ((hash2(x0, z0, this.seed + 1010 + i) * 7) | 0);
643	      const dz = z0 + ((hash2(x0, z0, this.seed + 1030 + i) * 6) | 0);
644	      if (dz === z0 + 3 && dx >= x0 + 1 && dx <= x0 + 4) continue;
645	      const block = i < 2 ? this.id.obsidian : this.ruinBlock(dx, g + 1, dz);
646	      this.put(dx, g + 1, dz, block);
647	    }
648	    this.put(x0, g + 1, zf, this.id.torch);
649	    this.put(x0 + 5, g + 1, zf, this.id.torch);
650	    return true;
651	  }
652	
653	  private buildCampsite(x0: number, z0: number): boolean {
654	    const g = this.ruinPad(x0, z0, 7, 7);
655	    if (g === null) return false;
656	    // Slab tent on four log posts.
657	    for (const [dx, dz] of [[1, 1], [3, 1], [1, 3], [3, 3]]) {
658	      this.put(x0 + dx, g + 1, z0 + dz, this.id.oak_log);
659	      this.put(x0 + dx, g + 2, z0 + dz, this.id.oak_log);
660	    }
661	    for (let z = z0 + 1; z <= z0 + 3; z++) {
662	      for (let x = x0 + 1; x <= x0 + 3; x++) this.put(x, g + 3, z, this.id.oak_slab);
663	    }
664	    this.put(x0 + 2, g + 1, z0 + 2, this.id.moss_block);
665	
666	    // Fire ring with a lantern, log seats, and supplies.
667	    this.put(x0 + 4, g, z0 + 3, this.id.cobblestone);
668	    this.put(x0 + 4, g + 1, z0 + 3, this.id.lantern);
669	    this.put(x0 + 3, g + 1, z0 + 4, this.id.oak_log);
670	    this.put(x0 + 5, g + 1, z0 + 3, this.id.oak_log);
671	    this.put(x0 + 5, g + 1, z0 + 2, this.id.bookshelf);
672	    this.put(x0 + 4, g + 1, z0 + 5, this.id.crafting_table);
673	    this.put(x0 + 2, g + 1, z0 + 5, this.id.torch);
674	    this.put(x0 + 6, g + 1, z0 + 4, this.id.torch);
675	    return true;
676	  }
677	
678	  private buildRuinWalls(x0: number, z0: number, wid: number, dep: number, shape: number): boolean {
679	    const g = this.ruinPad(x0, z0, wid, dep);
680	    if (g === null) return false;
681	
682	    const wallCell = (x: number, z: number, salt: number): void => {
683	      if (hash2(x, z, this.seed + 1100 + salt) < 0.16) return;
684	      const maxH = 1 + ((hash2(x, z, this.seed + 1130 + salt) * 3) | 0);
685	      for (let y = g + 1; y <= g + maxH; y++) {
686	        if (y > g + 1 && hash3(x, y, z, this.seed + 1160) < 0.12) continue;
687	        this.put(x, y, z, this.ruinBlock(x, y, z));
688	      }
689	    };
690	
691	    for (let x = x0; x < x0 + wid; x++) wallCell(x, z0, 1);
692	    for (let z = z0 + 1; z < z0 + dep; z++) wallCell(x0, z, 2);
693	    if (shape === 1) {
694	      for (let x = x0 + 1; x < x0 + wid; x++) wallCell(x, z0 + dep - 1, 3);
695	    } else {
696	      // A broken interior spur makes the L-shaped ruin read as a former room.
697	      for (let z = z0 + 2; z < z0 + dep; z++) wallCell(x0 + 3, z, 4);
698	    }
699	    // Rubble and mossy patches.
700	    for (let i = 0; i < 8; i++) {
701	      const rx = x0 + ((hash2(x0, z0, this.seed + 1200 + i) * wid) | 0);
702	      const rz = z0 + ((hash2(x0, z0, this.seed + 1230 + i) * dep) | 0);
703	      if (rx === x0 || rz === z0) continue;
704	      this.put(rx, g + 1, rz, i < 2 ? this.id.moss_block : this.ruinBlock(rx, g + 1, rz));
705	    }
706	    return true;
707	  }
708	
709	  private placeDesertRuin(): void {
710	    let best: { x: number; z: number; score: number } | null = null;
711	    for (let z = this.w.minWorldZ + 6; z <= this.w.maxWorldZ - 6; z += 6) {
712	      for (let x = this.w.minWorldX + 6; x <= this.w.maxWorldX - 6; x += 6) {
713	        if (this.w.biomeNameAt(x, z) !== 'desert') continue;
714	        const d = Math.hypot(x - this.spawn.x, z - this.spawn.z);
715	        if (d < 40 || d > 115) continue;
716	        const info = this.rectInfo(x - 3, z - 3, 7, 7);
717	        if (!info || info.g - info.lo > 2) continue;
718	        if (this.waterDistance(x, z, 54) < 44) continue;
719	        const score = hash2(x, z, this.seed + 1401) + Math.abs(d - 72) * 0.01;
720	        if (!best || score < best.score) best = { x, z, score };
721	      }
722	    }
723	    if (!best) return;
724	    const g = this.ruinPad(best.x - 3, best.z - 3, 7, 7, true);
725	    if (g === null) return;
726	    const x0 = best.x - 3, z0 = best.z - 3;
727	    // Low sandstone walls with collapsed gaps and a short slab lintel.
728	    for (let x = x0 + 1; x <= x0 + 5; x++) {
729	      if (hash2(x, z0 + 1, this.seed + 1440) < 0.3) continue;
730	      const hgt = 1 + ((hash2(x, z0 + 1, this.seed + 1450) * 3) | 0);
731	      for (let y = g + 1; y <= g + hgt; y++) this.put(x, y, z0 + 1, this.id.sandstone);
732	    }
733	    for (let z = z0 + 2; z <= z0 + 5; z++) {
734	      if (hash2(x0 + 1, z, this.seed + 1460) < 0.35) continue;
735	      const hgt = 1 + ((hash2(x0 + 1, z, this.seed + 1470) * 2) | 0);
736	      for (let y = g + 1; y <= g + hgt; y++) this.put(x0 + 1, y, z, this.id.sandstone);
737	    }
738	    this.put(x0 + 4, g + 3, z0 + 2, this.id.sandstone);
739	    this.put(x0 + 5, g + 3, z0 + 2, this.id.sandstone);
740	    this.put(x0 + 5, g + 3, z0 + 3, this.id.sandstone);
741	    this.put(x0 + 4, g + 1, z0 + 4, this.id.sandstone);
742	    this.put(x0 + 5, g + 1, z0 + 4, this.id.sandstone);
743	    this.sites.push({ type: 'desert_ruin', x: best.x, z: best.z });
744	  }
745	}
746	
747	export function generateStructures(world: World): StructureSite[] {
748	  const builder = new Builder(world);
749	  builder.run();
750	  return builder.sites;
751	}
